package es.foco.next.runtime;
import static org.junit.Assert.*;
import android.Manifest;import android.app.*;import android.content.*;import android.os.*;import java.time.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35) @LooperMode(LooperMode.Mode.PAUSED)
public class DailyReminderTest {
 private Context c;private AlarmManager alarms;private NotificationManager notifications;
 @Before public void init(){c=RuntimeEnvironment.getApplication();c.getSharedPreferences("foco-daily-reminder",0).edit().clear().commit();Shadows.shadowOf((Application)c).grantPermissions(Manifest.permission.POST_NOTIFICATIONS);alarms=c.getSystemService(AlarmManager.class);notifications=c.getSystemService(NotificationManager.class);}
 @Test public void reminderIsOffByDefaultAndDoesNotSchedule(){DailyReminder.ensure(c);assertFalse(DailyReminder.enabled(c));assertEquals(0,Shadows.shadowOf(alarms).getScheduledAlarms().size());}
 @Test public void oneNonWakeupInexactAlarmIsReusedAcrossAppOpens(){DailyReminder.configure(c,true,1200);DailyReminder.ensure(c);DailyReminder.ensure(c);assertEquals(1,Shadows.shadowOf(alarms).getScheduledAlarms().size());var alarm=Shadows.shadowOf(alarms).peekNextScheduledAlarm();assertEquals(AlarmManager.RTC,alarm.type);assertEquals(900000,alarm.getWindowLengthMs());assertFalse(alarm.allowWhileIdle);assertTrue(alarm.triggerAtTime>System.currentTimeMillis());}
 @Test public void disablingCancelsThePendingAlarm(){DailyReminder.configure(c,true,1200);DailyReminder.configure(c,false,1200);assertEquals(0,Shadows.shadowOf(alarms).getScheduledAlarms().size());}
 @Test public void deniedNotificationPermissionPreventsScheduling(){Shadows.shadowOf((Application)c).denyPermissions(Manifest.permission.POST_NOTIFICATIONS);DailyReminder.configure(c,true,1200);assertEquals(0,Shadows.shadowOf(alarms).getScheduledAlarms().size());}
 @Test public void receiverShowsAtMostOneSilentGenericNotificationPerDay(){DailyReminder.configure(c,true,1200);Intent event=new Intent("es.foco.next.DAILY_REMINDER").putExtra("day",LocalDate.now().toString());new DailyReminder().onReceive(c,event);assertEquals(1,Shadows.shadowOf(notifications).getAllNotifications().size());Notification n=Shadows.shadowOf(notifications).getAllNotifications().get(0);assertEquals("Un pequeño paso para ti",n.extras.getString(Notification.EXTRA_TITLE));notifications.cancelAll();new DailyReminder().onReceive(c,event);assertEquals(0,Shadows.shadowOf(notifications).getAllNotifications().size());assertEquals(1,Shadows.shadowOf(alarms).getScheduledAlarms().size());}
 @Test public void staleDeliveryAndDisabledReminderCannotNotify(){DailyReminder.configure(c,true,1200);new DailyReminder().onReceive(c,new Intent("es.foco.next.DAILY_REMINDER").putExtra("day",LocalDate.now().minusDays(1).toString()));assertEquals(0,Shadows.shadowOf(notifications).getAllNotifications().size());DailyReminder.configure(c,false,1200);new DailyReminder().onReceive(c,new Intent("es.foco.next.DAILY_REMINDER").putExtra("day",LocalDate.now().toString()));assertEquals(0,Shadows.shadowOf(notifications).getAllNotifications().size());}
 @Test public void bootReschedulesOnlyWhenEnabled(){new DailyReminder().onReceive(c,new Intent(Intent.ACTION_BOOT_COMPLETED));assertEquals(0,Shadows.shadowOf(alarms).getScheduledAlarms().size());DailyReminder.configure(c,true,1200);new DailyReminder().onReceive(c,new Intent(Intent.ACTION_BOOT_COMPLETED));assertEquals(1,Shadows.shadowOf(alarms).getScheduledAlarms().size());}
}
